llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "NHC, a cytidine analog with an N-hydroxy modification, is reported to have poor oral bioavailability in humans; this close structural relative of the query supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Uridine, a highly hydrophilic pyrimidine nucleoside, has an absolute oral bioavailability of less than 10% in humans; the query shares the ribosyl-pyrimidine scaffold and high polarity, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Levovirin, a polar nucleoside, has human oral bioavailability less than 10% due to very low permeability; this illustrates that polar nucleosides can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Fludarabine, a purine nucleoside analog, has an oral bioavailability of ~55% in patients; this is a contradictory example showing that some nucleoside analogs achieve high F, but it is less structurally transferable because of the purine base and different metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Ribavirin, a monocyclic azole nucleoside, has an absolute oral bioavailability of ~52% in healthy volunteers; this contradictory evidence indicates that not all polar nucleosides are poorly absorbed, but ribavirin lacks the cytidine-like deamination liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is 5-azacytidine, a polar ribosyl triazine nucleoside that is chemically unstable and subject to cytidine deaminase metabolism. The most transferable evidence from closely related cytidine/uridine analogs (NHC, uridine, levovirin) shows poor oral bioavailability (<10-20%), while the higher-F examples are less similar purine or triazole nucleosides. Therefore the prediction is low oral bioavailability (<20%).",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for azacitidine itself was retrieved.",
    "Molecule 1's records appear to describe cladribine rather than its cytidine-like SMILES, creating uncertainty about that evidence.",
    "Human absolute oral bioavailability for azacitidine is not directly represented in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

